sealed class NozyFfiException(message: String): kotlin.Exception(message) {
        
        class Message(message: String) : NozyFfiException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<NozyFfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): NozyFfiException = FfiConverterTypeNozyFfiError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeNozyFfiError : FfiConverterRustBuffer<NozyFfiException> {
    override fun read(buf: ByteBuffer): NozyFfiException {
        
            return when(buf.getInt()) {
            1 -> NozyFfiException.Message(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: NozyFfiException): ULong {
        return 4UL
    }

    override fun write(value: NozyFfiException, buf: ByteBuffer) {
        when(value) {
            is NozyFfiException.Message -> {
                buf.putInt(1)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalUInt: FfiConverterRustBuffer<kotlin.UInt?> {
    override fun read(buf: ByteBuffer): kotlin.UInt? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterUInt.read(buf)
    }

    override fun allocationSize(value: kotlin.UInt?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterUInt.allocationSize(value)
        }
    }

    override fun write(value: kotlin.UInt?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterUInt.write(value, buf)
        }
    }
}




