        val len = buf.getInt()
        return List<OrchardReceivedNoteFfi>(len) {
            FfiConverterTypeOrchardReceivedNoteFfi.read(buf)
        }
    }

    override fun allocationSize(value: List<OrchardReceivedNoteFfi>): ULong {
        val sizeForLength = 4UL
